import XCTest
import KwipMLCore
@testable import KwipMLApp

final class WorkflowObjectiveArtifactTests:XCTestCase {
    private struct Fixture:Decodable {
        let componentID:String,runID:String
        let manifest:JSONValue,recipe:JSONValue,mapping:LossTargetMapping,input:JSONValue
        let outputShape:[Int],evaluationCount:Int,trainingCount:Int
        let predictions:JSONValue,metrics:JSONValue,evaluation:JSONValue
        let predictionData:Data,metricsData:Data
    }
    private func encode(_ value:JSONValue)throws->Data {let e=JSONEncoder();e.outputFormatting=[.sortedKeys,.withoutEscapingSlashes];return try e.encode(value)}
    private func fixtures()throws->[Fixture] {try JSONDecoder().decode([Fixture].self,from:Data(base64Encoded:fixtureSnapshot)!)}
    private func context(_ f:Fixture,policy:TrainingSampleCapturePolicy = .factory)throws->WorkflowObjectiveArtifactContext {
        let config=try LossConfiguration.decodeRecipe(f.recipe)
        let source=WorkflowNodeAddress(domain:.control,localID:"objective") // Actual prepared factory control address.
        return try .init(recipe:LossRecipe(configuration:config,source:source,targetMapping:f.mapping),runID:f.runID,inputContract:TypedTensorContract(sample:f.input["sampleShape"]!.arrayValue!.map {Int($0.integerValue!)},dtype:.float32),outputSampleShape:f.outputShape,trainingCount:f.trainingCount,evaluationCount:f.evaluationCount,expectedEpochs:3,scalarization:.mean,device:.cpu,policy:policy)
    }
    private func pin(_ data:Data)->JSONValue {.object(["schemaVersion":1,"file":.string("predictions.json"),"sha256":.string(WorkflowPhaseArtifacts.hash(data)),"bytes":.integer(Int64(data.count))])}
    private func mutate(_ value:JSONValue,path:[String],replacement:JSONValue)->JSONValue {
        guard let first=path.first else {return replacement}
        if case .object(var object)=value {object[first]=mutate(object[first] ?? .null,path:Array(path.dropFirst()),replacement:replacement);return .object(object)}
        if case .array(var array)=value,let index=Int(first),array.indices.contains(index) {array[index]=mutate(array[index],path:Array(path.dropFirst()),replacement:replacement);return .array(array)}
        return value
    }
    func testActualEightCPUArtifactsKeepArbitraryOutputRolesAndHonestOptionalAccuracy()throws {
        for f in try fixtures() {
            let c=try context(f),data=f.predictionData
            let preview=try WorkflowObjectiveArtifacts.predictions(data,metadata:f.manifest,context:c)
            XCTAssertEqual(preview.rows.count,16);XCTAssertEqual(preview.rows[0].output.shape,f.outputShape)
            XCTAssertEqual(Set(preview.rows[0].targets.keys),Set(f.mapping.roles.map(\.role)))
            let metrics=try WorkflowObjectiveArtifacts.metrics(f.metricsData,context:c)
            XCTAssertEqual(metrics.count,3)
            XCTAssertEqual(metrics.last!.accuracy != nil,["loss_cross_entropy","loss_nll"].contains(f.componentID))
            let evaluation=try WorkflowObjectiveArtifacts.evaluation(f.evaluation,context:c)
            XCTAssertEqual(evaluation.observations,16)
            XCTAssertEqual(evaluation.rawPreview?.shape,f.evaluation["rawShape"]!.arrayValue!.map {Int($0.integerValue!)})
            XCTAssertEqual(preview.rows[0].objectiveOutput != nil,c.recipe.configuration.values["reduction"] == .string("none"))
            if f.componentID == "loss_triplet_margin" {XCTAssertEqual(preview.rows[0].output.shape,[3,2]);XCTAssertTrue(preview.rows[0].targets.isEmpty)}
            if f.componentID == "loss_ctc" {XCTAssertEqual(preview.rows[0].targets["input_lengths"]?.shape,[]);XCTAssertEqual(preview.rows[0].output.shape,[3,3])}
        }
    }
    func testFourCapturePermissionsRemainIndependentAndNoRowsAreInvented()throws {
        let f=try fixtures().first {$0.componentID == "loss_bce_with_logits"}!
        for activation in [false,true] {for rows in [false,true] {
            let c=try context(f,policy:.init(activationValues:activation,predictionRows:rows))
            var predicted=f.predictions
            if !rows {predicted["predictionRows"] = .array([])}
            let data=try encode(predicted),preview=try WorkflowObjectiveArtifacts.predictions(data,metadata:pin(data),context:c)
            XCTAssertEqual(preview.rows.count,rows ? 16:0)
            if rows {XCTAssertNotNil(preview.rows[0].objectiveOutput)}
            var evaluation=f.evaluation
            if !activation {evaluation=mutate(evaluation,path:["rawPreview","values"],replacement:.array([]));evaluation=mutate(evaluation,path:["rawPreview","captureStatus"],replacement:.string("omittedByPolicy"))}
            let decoded=try WorkflowObjectiveArtifacts.evaluation(evaluation,context:c)
            XCTAssertEqual(decoded.rawPreview?.values.isEmpty,!activation)
            if !rows {XCTAssertThrowsError(try WorkflowObjectiveArtifacts.predictions(encode(f.predictions),metadata:pin(encode(f.predictions)),context:c))}
            if !activation {XCTAssertThrowsError(try WorkflowObjectiveArtifacts.evaluation(f.evaluation,context:c))}
        }}
    }
    func testRepinnedShapeRoleDtypeRunAndObjectiveTamperingStillRefuses()throws {
        for f in try fixtures() {
            let c=try context(f)
            for mutation in 0..<5 {
                var value=f.predictions
                switch mutation {
                case 0:value["runID"] = .string(UUID().uuidString)
                case 1:value["evaluationCount"] = 15
                case 2:value=mutate(value,path:["predictionRows","0","output"],replacement:.array([.bool(true)]))
                case 3:value=mutate(value,path:["predictionRows","0","targets","fake"],replacement:.integer(0))
                default:value=mutate(value,path:["predictionRows","0","objectiveOutput"],replacement:.array([.bool(true)]))
                }
                let data=try encode(value)
                XCTAssertThrowsError(try WorkflowObjectiveArtifacts.predictions(data,metadata:pin(data),context:c),"\(f.componentID) mutation \(mutation)")
            }
            var eval=f.evaluation;eval["componentID"] = .string("loss_unknown")
            XCTAssertThrowsError(try WorkflowObjectiveArtifacts.evaluation(eval,context:c))
            eval=f.evaluation;eval["aggregationDenominator"] = .number(0)
            XCTAssertThrowsError(try WorkflowObjectiveArtifacts.evaluation(eval,context:c))
            var metrics=f.metrics;metrics=mutate(metrics,path:["0","accuracy"],replacement:.number(0))
            if !["loss_cross_entropy","loss_nll"].contains(f.componentID) {XCTAssertThrowsError(try WorkflowObjectiveArtifacts.metrics(encode(metrics),context:c))}
        }
    }
    func testScalarAndNestedTensorParserBoundsWithoutFakeSingletonDirection()throws {
        let scalar=try ObjectiveResultTensor(json:.number(0.25),shape:[],dtype:.float32)
        XCTAssertEqual(scalar.shape,[]);XCTAssertEqual(scalar.values,[0.25])
        let grid=try ObjectiveResultTensor(json:.array([.array([1,2]),.array([3,4])]),shape:[2,2],dtype:.float32)
        XCTAssertEqual(grid.values,[1,2,3,4])
        XCTAssertThrowsError(try ObjectiveResultTensor(json:.bool(true),shape:[],dtype:.float32))
        XCTAssertThrowsError(try ObjectiveResultTensor(json:.number(0.5),shape:[],dtype:.int64))
        XCTAssertThrowsError(try ObjectiveResultTensor(json:.array([1]),shape:[100000000,100000000],dtype:.float32))
        XCTAssertThrowsError(try ObjectiveResultTensor(json:.array([.array([1]),.array([2,3])]),shape:[2,2],dtype:.float32))
    }
    func testProjectionUsesFramedTablesScalarLabelsAndOnlyEligibleAccuracy()throws {
        for f in try fixtures() {
            let c=try context(f),preview=try WorkflowObjectiveArtifacts.predictions(f.predictionData,metadata:f.manifest,context:c),evaluation=try WorkflowObjectiveArtifacts.evaluation(f.evaluation,context:c)
            let sections=ObjectiveResultProjection.sections(preview:preview,evaluation:evaluation)
            XCTAssertEqual(sections.first?.id,"summary")
            XCTAssertTrue(sections.contains {$0.id == "produced" && !$0.rows.isEmpty})
            let summary=try XCTUnwrap(sections.first).rows
            XCTAssertEqual(summary.contains {$0.first == "Accuracy"},["loss_cross_entropy","loss_nll"].contains(f.componentID))
            if f.componentID == "loss_ctc" {XCTAssertTrue(sections.contains {$0.id == "target.input_lengths" && $0.caption.contains("scalar []")})}
            if f.componentID == "loss_triplet_margin" {XCTAssertEqual(sections.first {$0.id == "produced"}?.columns,["Observation","Anchor","Match","Nonmatch"])}
            XCTAssertEqual(sections.contains {$0.id == "individualScores"},c.recipe.configuration.values["reduction"] == .string("none"))
        }
    }
    func testActualBoundedBytesAndPartitionMutationsDoNotGrantEvidence()throws {
        let f=try fixtures().first {$0.componentID == "loss_mse"}!,c=try context(f)
        let huge=Data(repeating:32,count:1_000_001)
        XCTAssertThrowsError(try WorkflowObjectiveArtifacts.predictions(huge,metadata:pin(huge),context:c))
        var m=f.manifest;m["sha256"] = .string(String(repeating:"0",count:64))
        XCTAssertThrowsError(try WorkflowObjectiveArtifacts.predictions(f.predictionData,metadata:m,context:c))
        for path in [["rawShape"],["activeCount"],["device"]] {
            let replacement:JSONValue=path[0] == "rawShape" ? .array([16,1]):path[0] == "device" ? .string("mps"):.integer(15)
            XCTAssertThrowsError(try WorkflowObjectiveArtifacts.evaluation(mutate(f.evaluation,path:path,replacement:replacement),context:c))
        }
        let metrics=mutate(f.metrics,path:["0","objective","training","activeCount"],replacement:.integer(47))
        XCTAssertThrowsError(try WorkflowObjectiveArtifacts.metrics(encode(metrics),context:c))
    }
    private let fixtureSnapshot=""
}

private extension JSONValue {
    subscript(_ key:String)->JSONValue? {
        get {if case .object(let object)=self {return object[key]};return nil}
        set {if case .object(var object)=self {object[key]=newValue;self = .object(object)}}
    }
    var arrayValue:[JSONValue]? {if case .array(let array)=self {return array};return nil}
}
